corrected_code:
app.post('/api/security/:id/action', async (req, res) => {
  const user = req.user;
  const target = await SecurityPref.findById(req.params.id);
  if (target.userId.toString() !== user.id) return res.status(403).send('Forbidden');
  target.applyAction(req.body.actionData);
  await target.save();
  res.send('Done');
});
